import ast, pathlib
for p in sorted(pathlib.Path('ledgerly').rglob('*.py')):
    if p.name in ('money.py','__init__.py'): continue
    t = ast.parse(p.read_text())
    print('##', p)
    for n in t.body:
        if isinstance(n, ast.FunctionDef):
            ret = ast.unparse(n.returns) if n.returns else ''
            args = ', '.join(ast.unparse(a.annotation) if a.annotation else a.arg for a in n.args.args)
            print(f'  {n.name}({args}) -> {ret}')
            # print return statement expr
            for s in ast.walk(n):
                if isinstance(s, ast.Return):
                    print('     return', ast.unparse(s.value))
